// Original revision summaries, written from the structure and ideas in the supplied
// Cambridge IGCSE ICT coursebook and supplementary lesson notes. Not book extracts.
const lesson=(title,points,example,tip,terms=[])=>({title,points,example,tip,terms});
const chapter=(id,title,description,lessons)=>({id,title,description,unit:id<=11?"Theory":"Practical",lessons});
export const chapters=[
chapter(1,"Types and components of computer systems","Understand what a computer contains and how its parts work together.",[
lesson("Hardware and software",["Hardware is the physical equipment, including the processor, motherboard, memory and peripherals.","Application software helps people complete tasks such as editing documents. System software runs and maintains the computer.","A device driver allows an operating system to communicate with a particular piece of hardware.","The motherboard connects internal components. A graphics card generates display output, a sound card handles audio and a NIC connects to a network.","Application types: word processing creates documents, spreadsheets calculate and model, databases store and query records, CAD produces technical drawings, graphics/audio/video editors modify media, control software operates equipment and measurement software collects readings. Apps and applets perform specific tasks.","A compiler translates source code into executable or intermediate code; a linker combines compiled modules and libraries. Utilities maintain the system, such as backup, compression and malware scanning."],"A school purchases laptops. The keyboards, screens and SSDs are hardware. Its word processor is application software and its operating system is system software.","For comparison questions, name a feature and explain why it matters.",[["Hardware","The physical components of a computer."],["System software","Programs that manage hardware and provide a platform for applications."],["Application software","Programs designed for specific user tasks."],["Motherboard","Main circuit board linking computer components."],["Utility software","System software used to maintain or protect a computer."]]),
lesson("Processor and internal memory",["The CPU executes instructions. Its control unit coordinates operations, the ALU performs calculations and comparisons, and registers temporarily hold data.","RAM holds programs and data in use and loses its contents without power. ROM retains start-up instructions without power.","Backing storage, unlike RAM, retains documents and software when the computer is turned off.","ROM retains firmware used during start-up and is normally not changed by ordinary programs. RAM is read/write working memory. Backing storage keeps files long term and normally has greater capacity but slower access than RAM.","Input devices supply data; output devices communicate results or perform physical actions. A touchscreen performs both roles."],"A pupil opens a presentation. The file is loaded from an SSD into RAM so the CPU can work with it.","RAM is volatile. ROM is non-volatile. Avoid confusing ROM with optical CD-ROM media.",[["RAM","Volatile working memory used by running programs."],["ROM","Non-volatile memory containing start-up instructions."],["CPU","The component that processes program instructions."],["Volatile memory","Memory that loses its contents when power is removed."],["Non-volatile memory","Memory that retains its contents without power."]]),
lesson("Digital signals and interfaces",["Analogue values change continuously while digital values use fixed levels represented by binary digits.","An analogue-to-digital converter (ADC) lets a computer read analogue signals. A digital-to-analogue converter (DAC) drives analogue outputs.","GUIs use windows and icons. CLIs use typed commands. Other interfaces include dialogue and gesture input.","An operating system manages memory, processor time, files, peripherals, user accounts and the interface; applications depend on its services.","CLI users type commands; GUI users select windows, icons, menus and pointers (WIMP). Dialogue interfaces accept spoken commands, while gesture interfaces detect body movements.","An ADC samples analogue readings such as a microphone signal for digital processing. A DAC converts digital output to an analogue signal for speakers or analogue actuators."],"A temperature sensor produces an analogue value. An ADC converts it so a control program can process it.","A sensor does not always require a DAC. Mention DAC only when the output device requires analogue control.",[["ADC","Converts an analogue signal into digital data."],["GUI","An interface based on visual controls such as icons and menus."],["CLI","Text-based interface operated by commands."],["DAC","Device converting digital signals to analogue form."],["Operating system","Software managing computer resources and providing services to applications."]]),
lesson("Computer types and emerging technology",["Desktops offer upgrade options and fixed working space. Laptops add portability, while tablets and phones prioritise touch input and battery operation.","Choose a device by screen size, software needs, input method, weight, battery life and price.","Virtual reality places users in a simulated environment. Augmented reality adds digital information to the real environment.","A phablet is a large smartphone; laptops support mobile office tasks, tablets support touch-based learning and smartphones support calls, navigation and remote device control.","AI performs tasks such as recognising patterns and making recommendations; machine learning learns patterns from examples. Biased training data can lead to unfair results.","VR replaces the user's surroundings with a simulated environment for training or virtual tours. AR adds digital objects to a real view, such as navigation directions or furniture previews."],"A designer making large CAD drawings benefits from a desktop workstation and large display. A field worker benefits from a light tablet.","AR adds to reality. VR replaces the user's view of reality.",[["Augmented reality","Digital objects or information overlaid on the real world."],["Virtual reality","An interactive computer-generated environment."],["Artificial intelligence","Technology performing tasks associated with human intelligence."],["Phablet","Large-screen smartphone with features of a tablet."]])
]),
chapter(2,"Input and output devices","Select suitable devices and explain how data enters and leaves a system.",[
lesson("Manual and direct input",["Keyboards, mice, touchscreens, cameras and microphones are examples of input devices.","Direct data entry reduces retyping by collecting encoded data, for example with barcode readers, RFID readers, OCR or OMR.","OCR converts images of printed characters to text. OMR detects marked positions on a form.","A numeric keypad enters PINs and numbers; mice, touchpads and trackerballs move a pointer; remote controls operate equipment at a distance; joysticks and driving wheels control movement in simulations.","Resistive touchscreens respond to pressure; capacitive touchscreens detect changes in capacitance. Scanners digitise paper, cameras capture images/video, webcams provide live video and microphones capture sound. Light pens select or draw on compatible displays; a graphics tablet uses a stylus.","Magnetic stripe readers read stored card data; chip and PIN readers read chip data and authenticate using a PIN. RFID readers use radio waves, often without direct line of sight; QR readers use a camera and software to decode two-dimensional codes.","Barcode readers identify products using reflected light or imaging; the identifier retrieves the price from a database, rather than normally storing the price itself. OCR turns printed characters into editable text; OMR detects positions of marked boxes."],"A school marks shaded answer sheets with OMR and reads printed candidate numbers with OCR.","Mention a named input device and connect its strengths to the scenario.",[["OCR","Recognition of characters from a scanned image."],["OMR","Detection of marks in predetermined positions."],["RFID","Identification of tagged objects using radio waves."],["QR code","Two-dimensional code containing machine-readable information."],["Direct data entry","Capturing data without manually retyping it."]]),
lesson("Sensors and control",["A sensor measures a property such as temperature, pressure, light, movement or proximity.","The system converts an analogue reading through an ADC when needed, compares it with a stored condition, then determines a response.","An actuator, motor or alarm provides a physical output when instructed.","Temperature sensors monitor greenhouses; pressure sensors detect loads or intruders; light sensors control streetlights; moisture sensors control irrigation; proximity or motion sensors detect nearby objects. Sensors provide automatic readings but may fail or need calibration.","In monitoring, readings are recorded or warnings displayed. In control, the processor compares readings with preset values and operates an actuator, then repeats the measurement as feedback."],"A greenhouse switches on a heater when the temperature sensor reports a reading below the target.","Use the sequence input → conversion → comparison → decision → output.",[["Sensor","An input device that measures a physical condition."],["Actuator","An output device that produces a physical action."],["Feedback","Using new readings to check the result of a control action."]]),
lesson("Choosing output devices",["Monitors and projectors display information. Speakers and buzzers output sound.","Inkjet printers suit detailed colour pages. Laser printers suit frequent, fast printing. Dot-matrix printers strike ribbons and suit multipart forms.","Plotters produce large precise drawings and 3D printers build physical objects layer by layer.","LCD and LED-backlit monitors display soft copy; touchscreens also accept input. Multimedia projectors display images to large audiences but bright rooms reduce visibility.","Laser printers use toner and heat for fast printing; inkjets spray droplets for detailed colour; dot-matrix printers strike a ribbon and can print multipart forms. Plotters produce large precise plans. 3D printers build objects in layers from a digital model.","Speakers produce audio, including screen-reader output. Actuators such as motors, heaters and valves cause physical changes in controlled systems."],"A reception desk printing hundreds of monochrome letters daily is better matched with a laser printer than a slow inkjet.","Explain the intended use, speed, output quality, running cost and environment.",[["Output device","Hardware that delivers processed information or an action."],["Plotter","An output device suited to accurate large-format drawings."],["Hard copy","Physical printed output."],["Soft copy","Electronic output displayed or stored digitally."]])
]),
chapter(3,"Storage","Compare magnetic, optical and solid-state storage in context.",[
lesson("Devices, media and capacity",["A storage device reads and writes information. The medium holds the data.","Backing storage is non-volatile. Consider capacity, transfer speed, durability, portability and cost when choosing it.","Never mix up backing storage and temporary RAM.","Eight bits form one byte; common decimal storage units increase by factors of 1000 (KB, MB, GB, TB). Compare devices using capacity, access speed, portability, durability and cost per unit of storage."],"A DVD is a storage medium. A DVD drive is the device used to read it.","A scenario requiring frequent random access is different from long-term backup.",[["Storage medium","The material on which data is stored."],["Backing storage","Non-volatile storage for saved programs and files."],["Storage device","Equipment that reads or writes data on storage media."]]),
lesson("Magnetic and optical storage",["Hard disk drives use spinning magnetic surfaces. Magnetic tape supports economical sequential backup.","CDs, DVDs and Blu-ray discs use lasers to read marks on an optical surface.","Optical formats differ in capacity. Recordable discs are written once while rewritable discs support repeated writing.","Fixed HDDs provide large inexpensive storage; portable HDDs support transfers and backups but moving parts are vulnerable to shocks. Magnetic tape offers large archival capacity but uses sequential access.","Optical drives use lasers to read CDs, DVDs and Blu-ray discs. Typical single-layer capacities are about 700 MB, 4.7 GB and 25 GB respectively. ROM discs are read-only, R discs record once and RW/RE discs are rewritable."],"An organisation keeps archived backup copies on magnetic tape, where access speed is less important than capacity.","A magnetic tape is not ideal when a user needs to open any record instantly.",[["Magnetic storage","Data stored using magnetised regions."],["Optical storage","Data read using light from a laser."],["Sequential access","Reading records in order until the required record is reached."],["Direct access","Accessing a required location without reading all earlier records."]]),
lesson("Solid-state storage",["SSDs, USB flash drives and memory cards use electronic flash memory and contain no moving read heads.","Solid-state devices resist mechanical shock and offer fast access, but price per gigabyte depends on the device.","Use portable media with appropriate protection and make separate backups of irreplaceable data.","Fixed and portable SSDs store data electronically. USB pen drives are compact removable flash storage; SD, xD and CFast memory cards suit compatible cameras and portable equipment. Small media are easy to lose; flash has finite write endurance."],"A laptop carried between classrooms benefits from an SSD because it handles movement and starts programs quickly.","Do not say solid-state storage is volatile. Flash memory retains data without power.",[["SSD","A drive storing data in solid-state flash memory."],["Flash memory","Non-volatile electronic storage commonly used in portable devices."],["Memory card","Small removable solid-state storage medium."]])
]),
chapter(4,"Networks","Explain connections, protocols, network equipment and data protection.",[
lesson("LAN, WAN and wireless",["A LAN covers a site such as a school. A WAN connects sites over a wider geographical area.","A WLAN uses radio signals to connect devices on a local network. Wi-Fi generally provides greater network reach than Bluetooth.","An intranet is private to an organisation. An extranet provides controlled access to selected outsiders.","Wi-Fi connects a device to an access point by selecting a network and authenticating. Bluetooth pairs nearby devices for tasks such as connecting headphones or exchanging small files. Both use radio signals; Wi-Fi generally has greater range and throughput, Bluetooth often uses less power.","The internet is a global public network; an intranet restricts access to an organisation, while an extranet grants selected external users controlled access."],"A school has a LAN within its campus and connects to other campuses through a WAN.","A WLAN is still a LAN, but its local connections are wireless.",[["LAN","A network covering a limited geographical area."],["WAN","A network spanning a wide geographical area."],["Intranet","Private network content restricted to an organisation."],["WLAN","Local area network using wireless links."],["Extranet","Private network resources made available to authorised external users."]]),
lesson("Network hardware",["A network interface card links a device to a network. A switch directs frames to the intended local device.","A router forwards packets between networks. A wireless access point connects wireless clients to a network.","Networks share resources but require administration and security.","A bridge links LAN segments and filters traffic using hardware addresses. A hub repeats incoming data to all other ports; a switch forwards frames using a learned address table. A NIC gives a device network connectivity.","A router reads destination network addresses, consults routing information and forwards packets towards their destinations; a home router connects a local network to the internet and commonly manages local IP address assignments."],"A school's computers use switches on each floor and a router to reach an outside network.","A hub broadcasts to connected ports, while a switch targets the destination.",[["Router","Equipment that directs data between networks."],["Switch","Equipment that connects local devices and forwards data to the destination."],["Bridge","Device connecting network segments and filtering traffic between them."],["Packet","Unit of data sent across a network."]]),
lesson("Security and cloud services",["Threats include unauthorised access, malicious software and intercepted transmissions.","Encryption protects the meaning of data when a secret key is not available. Firewalls filter traffic according to rules.","Cloud services store data on remote systems and support access from multiple devices, subject to connection and privacy risks.","Cloud data is held on remote servers managed by a provider. Users authenticate, upload or synchronise files and share access using permissions. Benefits include remote access and collaboration; drawbacks include outages, subscription costs and privacy concerns.","Confidential transfers use encryption and authenticated connections. Strong unique passwords, updated anti-spyware and secure password handling reduce interception risks; follow organisational password-change rules and change compromised passwords promptly.","Authentication methods include fingerprints and other biometrics, magnetic stripe or smart cards, hardware tokens, one-time electronic codes and zero login using recognised behavioural patterns.","Anti-malware checks downloads and removable media, detects suspicious files and removes or isolates them in quarantine. Keep detection software updated."],"A pupil reaches their school files at home using cloud storage, but needs an internet connection and secure sign-in.","Never claim that encryption prevents theft. It makes stolen data harder to interpret.",[["Encryption","Encoding data so it is unreadable without the required key."],["Firewall","A system that controls network traffic using rules."],["Quarantine","Isolation of a suspicious file to prevent it affecting other files."],["Zero login","Authentication based on recognised user behaviour or characteristics without a conventional login."]]),
lesson("Electronic conferencing",["Audio conferencing uses microphones, speakers or headsets, conferencing software and a network connection; video conferencing also needs cameras and displays.","Web conferencing adds browser-based meeting tools such as screen sharing, chat, shared documents and presentations. Participants connect to a meeting using a link or meeting ID.","Remote meetings reduce travel costs and time and enable participants in different locations to meet; drawbacks include poor connections, reduced non-verbal cues, time zones and confidentiality concerns."],"A school holds a remote parent meeting with a webcam, headset, conferencing service and internet connection.","Name hardware, software and connectivity separately when asked about setup.",[["Video conferencing","Real-time communication using audio and moving images."],["Web conferencing","Online meetings supporting shared web-based resources and communication."]])
]),
chapter(5,"The effects of using IT","Evaluate smart devices, transport technology and safe computer use.",[
lesson("Microprocessor-controlled homes",["Microprocessors control appliances using stored instructions and input from sensors.","Smart devices also exchange information over networks and sometimes allow remote control through phones.","Benefits include convenience and automated monitoring. Risks include hacking, dependence on connectivity, high costs and reduced physical activity.","Automatic heating, washing and security devices save time, provide leisure and may improve accessibility. Reduced manual effort can lower physical activity, increased device use may reduce face-to-face interaction, and connected devices collect data vulnerable to misuse.","Smart alarms allow remote monitoring but depend on power, sensors and secure connectivity."],"A smart fridge checks its inventory and sends a shopping alert. A normal microprocessor fridge regulates cooling without the same internet features.","Use precise cause-and-effect links, for example remote monitoring helps a carer react earlier.",[["Internet of Things","Physical devices connected to exchange data over networks."]]),
lesson("Transport systems",["Parking sensors and reversing cameras warn about nearby objects.","Anti-lock braking, lane alerts and tyre pressure monitoring assist with vehicle safety.","Faulty sensors, false alarms and over-reliance on automated alerts can create risks.","Autonomous vehicles use sensor readings to identify surroundings and adjust steering, braking and speed. Benefits include consistent reactions and potential reductions in driver error; limitations include sensor faults, difficult conditions, hacking, privacy risks and responsibility for accidents."],"A parking sensor detects a close obstacle and warns the driver, who must still check surroundings.","In a discuss question, develop both a benefit and a limitation rather than listing devices.",[]),
lesson("Health and working practices",["Poor posture and repetitive movements may cause back pain or repetitive strain injury.","Screen glare, long uninterrupted sessions and incorrect viewing distances contribute to eye strain.","Use adjustable seating, suitable lighting, regular breaks and correct screen and keyboard positioning.","RSI results from repetitive typing or mouse movements; use ergonomic input devices, neutral wrist position and breaks. Back pain results from poor posture; adjust chair height, lumbar support and screen position. Eye strain and headaches may follow glare or prolonged close viewing; adjust lighting, screen brightness and take regular visual breaks."],"A learner adjusts the chair so wrists stay straight and takes screen breaks during a long study session.","Distinguish a physical safety hazard, such as trailing cables, from a health issue caused by long use.",[["RSI","Discomfort or injury associated with repeated movement over time."]])
]),
chapter(6,"ICT applications","Apply ICT ideas to communication, modelling, control and services.",[
lesson("Communication systems",["Newsletters, websites, presentations and digital publications communicate to different audiences.","Mobile communication includes calls, SMS, video calls and Voice over Internet Protocol (VoIP).","Streaming plays received media while later parts are still arriving. A buffer stores incoming data to reduce interruptions.","Posters communicate short visual messages, newsletters provide periodic updates, websites provide interactive information, multimedia presentations combine text and media, and ePublications provide electronic reading material. Mobile devices support internet access, SMS, calls, VoIP and video communication."],"A streamed lesson starts before the complete video has arrived. Downloading saves the complete file for later offline viewing.","Compare streaming and downloading using time to start, connection dependence, storage and buffering.",[["Streaming","Playing media while it is being transferred."],["VoIP","Voice communication carried over internet-protocol networks."]]),
lesson("Modelling and computer control",["A model tests possible outcomes without requiring an expensive or dangerous real-world trial.","Simulation helps with weather predictions, traffic flow, financial planning and training.","Computer-controlled systems use sensors, processing and actuators to respond to their surroundings.","Models estimate personal finances, bridge/building stresses, flood water behaviour, traffic flow and weather. Changing inputs supports what-if analysis without real-world expense or danger, but inaccurate assumptions and data produce unreliable predictions.","Manufacturing robots and production-line controllers perform repetitive operations consistently, work in hazardous environments and reduce labour costs. They require installation, maintenance and skilled support, may displace workers and may stop production if a fault occurs."],"A town models different road layouts before spending money on construction.","A model is limited by its assumptions and the quality of its data.",[["Simulation","A computer-based imitation of a real process or situation."]]),
lesson("Expert systems",["An expert system supports decisions in a narrow specialist area.","Its knowledge base stores facts and rules. The inference engine applies rules to the user's input. The interface collects questions and returns advice.","Expert systems are useful when expertise is costly or unavailable, but unusual cases and inaccurate input may produce poor advice.","Five components to distinguish: user interface collects facts; knowledge base holds domain facts; rules base contains decision rules; inference engine applies those rules; explanation system shows how a conclusion was reached.","The system asks questions, matches answers to facts and rules, asks further questions if needed, then presents possible solutions and explanations. Applications include medical diagnosis, engine faults, mineral prospecting, chess, financial planning, delivery route scheduling and species identification."],"A mechanic enters engine symptoms. The inference engine checks rules in the knowledge base and proposes likely faults.","Name all three components and explain their distinct roles.",[["Knowledge base","The facts and rules stored for an expert system."],["Inference engine","The component that applies stored rules to user information."],["Rules base","Stored decision rules used by an expert system."],["Explanation system","Component explaining the reasoning behind a recommendation."]]),
lesson("Booking, banking and recognition",["Online booking checks availability and reserves a service, potentially updating records instantly.","Banking systems support transfers, ATMs and online transactions with authentication and fraud controls.","Recognition systems use technologies such as barcodes, RFID, biometrics and automatic number plate recognition.","Online booking displays available seats or rooms, temporarily reserves a selection, accepts payment, updates availability and sends confirmation. Examples include flights, hotels, cinema, concerts and sports.","ATM operations include cash withdrawals and deposits, cheque deposits, balance checks, mini statements, bill payments and transfers. A card and PIN authenticate the customer; the bank checks account status and funds, then authorises or rejects the request.","EFT transfers money electronically. Debit payments draw from an account; credit payments use a credit facility. Cheques are processed and cleared before settlement. Internet banking provides account access without visiting a branch.","ANPR captures a vehicle image, locates the number plate and uses OCR to identify characters for comparison with records. RFID tracks stock, passports and vehicles; NFC supports close-range contactless payments. Biometrics compare captured face, iris, retina, fingerprint, thumb, hand or voice characteristics with stored templates."],"A cinema booking system must stop two people from purchasing the same seat.","Use the specific application in an answer, rather than general statements about computers.",[["EFT","Electronic transfer of money between accounts."],["ANPR","Automatic identification of vehicle registration numbers from images."],["NFC","Short-range wireless communication used for tasks such as contactless payment."]]),
lesson("Medicine, retail and satellites",["Computers help with patient records, imaging, remote care and monitoring.","Retail uses point-of-sale systems, stock databases and automatic replenishment.","Satellites support communications, navigation and monitoring across wide areas.","Patient records hold history, diagnoses, treatments and test results; pharmacy systems track prescriptions, dosage, interactions and medicine stock. Restrict access to authorised staff.","3D printing in medicine produces customised prostheses, tissue-engineering structures, artificial blood vessels and tailored medicines; clinical suitability must be checked.","POS scans a product identifier, retrieves description and price, calculates totals and reduces stock. If stock falls below a reorder level, the system generates an order. EFTPOS communicates transaction information to the bank, which validates payment and returns authorisation. Chip and PIN, contactless cards and NFC phones support payment.","Online shopping allows customers to compare products and order remotely but relies on delivery, secure payment and accurate descriptions.","GPS uses signals from multiple satellites to calculate location; satellite navigation combines location with digital maps and route guidance. GIS stores and analyses geographically referenced layers, such as flood-risk maps. Satellite television and satellite phones carry communications over wide areas; obstructions, delay and weather can affect services."],"A supermarket's till reduces recorded stock after a scanned sale.","For ICT applications, identify input, processing and output in the example.",[["POS","Point-of-sale system recording sales and updating stock."],["EFTPOS","Electronic payment system at a point of sale."],["GIS","System storing, analysing and displaying geographic data."]]),
lesson("School management systems",["A school information system stores pupil details and uses registration records to monitor attendance and identify absences.","Teachers enter assessment results and produce progress reports, compare attainment with targets and identify pupils needing support.","Computer-aided learning gives interactive exercises, immediate feedback and records performance; it supports individual pacing but does not replace teaching."],"A tutor checks attendance and assessment records before a parent meeting.","Explain how recorded data is used rather than only naming the system.",[["Computer-aided learning","Use of computer software to support learning and track progress."]])
]),
chapter(7,"The systems life cycle","Follow the stages of designing and introducing a new system.",[
lesson("Analysis",["Before creating a replacement system, record problems and the user's requirements.","Fact-finding methods include interviews, observation, questionnaires and examining existing documents.","Create measurable requirements so the new system can be assessed against them.","Record existing inputs, processing and outputs, identify problems, establish user and information requirements, then justify hardware and software choices in the system specification. Observation shows real working practices but users may behave differently; documents reveal existing data and formats but may be outdated."],"A library interviews staff and observes loans before deciding which records its new system must hold.","An interview gives detailed answers, while a questionnaire reaches many respondents consistently.",[["Analysis","Investigating the existing system and identifying requirements."]]),
lesson("Design and validation",["Design inputs, outputs, file structures, user interfaces and the processing required.","Validation checks whether entered data follows rules. Examples include type, range, length, presence and format checks.","A test plan identifies the data, expected outcomes and actual outcomes.","Specify field names, types, lengths and codes, input forms with clear labels, and output/report layouts. Range checks test limits, character checks restrict permitted characters, length checks test size, type checks test data type, format checks test patterns, presence checks reject blanks and check digits detect certain transcription errors."],"A date-of-birth form rejects a future date using a range or logical check.","Validation does not prove that data is factually correct.",[["Validation","Checking input against predefined rules."],["Verification","Checking that entered data matches the original source."],["Check digit","Calculated digit used to detect some errors in entered identifiers."]]),
lesson("Testing and implementation",["Test normal, abnormal and extreme values, and compare results with expectations.","Direct changeover is quick but risky. Parallel running keeps the old system operating during transition.","Pilot changeover starts with one area. Phased changeover introduces functions in stages.","Test individual modules, functions and the complete system, including file structures, forms, reports and validation. A test plan records inputs, expected and actual results, corrective action and retest results.","For a permitted range of 1–100, normal data is 50, extreme valid data is 1 or 100, abnormal data is 0 or 101. Live data is real operational data used to check realistic performance safely."],"A school tests its attendance system with empty names, valid names and maximum-length entries.","Know one advantage and one disadvantage of each changeover method.",[["Parallel running","Operating old and new systems together during changeover."],["Pilot running","Introducing a new system to a limited group first."],["Extreme test data","Valid values at the boundaries of the permitted range."],["Abnormal test data","Invalid input that should be rejected."]]),
lesson("Documentation and evaluation",["Technical documentation explains structure, program design and maintenance details.","User documentation explains how to operate the system and handle problems.","Evaluation compares the installed system against the original requirements using evidence from users.","Technical documentation supports maintenance: system purpose and limitations, hardware/software requirements, file structures, variables, program listings and language, system/program flowcharts or algorithms, input/output formats, validation and test runs.","User documentation supports operation: installation and running, saving and printing, adding/editing/deleting records, input/output formats, examples, error messages, troubleshooting, helpline, FAQ and glossary.","Evaluate efficiency, ease of use and suitability against original requirements; collect user feedback and test evidence, identify limitations and propose specific improvements."],"After installation, staff report whether generating an attendance list meets the planned speed target.","Evaluation is about meeting requirements, not simply declaring that the system works.",[])
]),
chapter(8,"Safety and security","Keep people, devices and data safe in digital environments.",[
lesson("Physical safety and e-safety",["Secure cables, avoid overloaded sockets and keep liquids away from electrical equipment.","Limit the personal details shared in public profiles, use privacy settings and report threatening contact.","Treat unexpected messages and attachments carefully, even if a visible sender name looks familiar.","Prevent electric shock by keeping liquids away and replacing damaged cables; avoid overloaded sockets and blocked ventilation to reduce fire risk; secure trailing cables and place heavy equipment on stable surfaces.","Typical data protection principles: process personal data fairly and lawfully for specified purposes; keep only necessary, accurate data for no longer than needed; protect it securely and respect people's access and correction rights. Sensitive information such as health records needs particular protection.","Use trusted and age-appropriate sites; avoid replying to suspicious email or sharing identifiable images; block and report abusive social media users, avoid meeting strangers alone, respect others' privacy and use aliases in online games without sharing payment or personal details."],"A pupil hides their live location on a social account and reports a suspicious message instead of opening its link.","E-safety concerns people online. Physical safety concerns hazards around equipment.",[["E-safety","Safe and responsible behaviour when using online services."],["Personal data","Information relating to an identifiable person."],["Sensitive personal data","Personal information requiring particular protection, such as health information."]]),
lesson("Online attacks and fraud",["Phishing uses deceptive messages. Pharming redirects users to fake websites. Smishing and vishing use messages and voice calls.","Malware includes viruses, spyware, ransomware and other unwanted programs.","Shoulder surfing, keylogging and card cloning are ways criminals obtain payment or login details.","Hacking is unauthorised access; reduce risk using access controls, updates and firewalls. Verify unexpected messages through a trusted contact route and avoid suspicious links to counter phishing, smishing and vishing. Use trusted URLs and secure DNS/browser settings to reduce pharming risks.","Viruses attach to files and spread when executed; worms spread across networks; Trojans disguise malicious software; spyware collects information. Scan downloads and removable media, update software and avoid untrusted files.","Protect card details by shielding PIN entry, checking terminals for tampering and monitoring transactions. Keyloggers record keystrokes; use trusted devices and anti-malware."],"A fake bank text asking for a password is smishing. A fraudulent telephone call asking for it is vishing.","Name the exact attack and explain how it works.",[["Phishing","A deceptive attempt to obtain information or cause unsafe actions."],["Ransomware","Malware that restricts access to data and demands payment."],["Pharming","Redirecting users to fraudulent websites even when they intend to visit a genuine site."],["Smishing","Phishing through text messages."],["Vishing","Phishing through voice calls."]]),
lesson("Protecting information",["Use strong unique passwords and an additional authentication factor when available.","Apply security updates and anti-malware protection. Use backups and permissions to limit damage.","Encryption protects data confidentiality, while HTTPS helps protect data travelling between a browser and website.","A digital certificate binds a website or entity's identity to a public key; it contains identifying details, issuer, validity period, public key and issuer signature. SSL is the older term for encrypted client-server links; modern HTTPS uses TLS.","Encryption protects stored drives, email, cloud files and HTTPS traffic from unauthorised reading. Firewalls filter network traffic. User IDs identify accounts and passwords authenticate them; 2FA uses two different factor categories: knowledge, possession or biometric characteristic."],"A club restricts its member database to authorised staff and keeps an encrypted backup.","Authentication checks identity. Authorisation controls permitted actions.",[["Authentication","Checking that a user is who they claim to be."],["Encryption","Transforming data to protect it from unauthorised reading."],["Digital certificate","Electronic credential linking an identity to a public key."],["Two-factor authentication","Identity checking using two different categories of evidence."]])
]),
chapter(9,"Know your audience","Make communication readable, appropriate and lawful.",[
lesson("Audience and purpose",["Tailor language, layout, graphics and technical detail to the people reading or watching.","Consider visual accessibility, contrast, font size and the device on which material will be viewed.","Avoid crowding pages with decorative effects that distract from the message.","Analyse age, language, interests, technical knowledge, accessibility, culture and purpose before selecting content and medium. Use readable type, suitable images, respectful language, alternative text and clear navigation."],"A primary-school poster needs brief sentences and clear illustrations. A report for technicians needs accurate detail.","In an evaluation, link each design choice to the intended audience.",[["Audience","The people a document, site or presentation aims to reach."]]),
lesson("Copyright and licences",["Copyright protects original creative work such as writing, software and images.","Check licence conditions before copying, adapting or sharing someone else's work.","Attribute permitted sources properly and avoid publishing restricted coursebook pages or mark schemes.","Software piracy includes unauthorised copying, installation beyond licence limits and distribution. Copyright protects creators and their income; follow licence restrictions. Producers discourage piracy through product activation, licence keys, account checks, copy protection and licence agreements."],"A student uses an image with permission and includes the required creator credit.","A publicly visible resource is not automatically free to republish.",[["Intellectual property","Creations such as writing, software, artwork and designs protected by law."],["Software piracy","Unauthorised copying or distribution of software."]])
]),
chapter(10,"Communication","Use email, the web and online tools effectively.",[
lesson("Email and online communication",["An email includes recipient fields, subject, message and optional attachments.","CC shares with visible additional recipients. BCC hides additional recipients from other recipients.","Use appropriate subject lines, polite wording and careful review before sending.","Email groups distribute messages to many recipients; forwarding passes a received message onward. Attachments are limited by size and file compatibility; email requires access and is not always read immediately. Follow workplace rules and netiquette, avoid offensive language and check recipients before sending.","Spam is unsolicited bulk email that wastes time and storage and may contain scams or malware. Use spam filters, block/report senders, protect email addresses and avoid responding to suspicious messages."],"A school message BCCs a list of parents so their email addresses are not exposed to one another.","Never open attachments from untrusted senders.",[["BCC","A recipient field that hides those addresses from other recipients."],["Spam","Unsolicited bulk electronic messages."]]),
lesson("Internet, web and searching",["The internet is the global network infrastructure. The World Wide Web is a service that uses it.","A browser displays web pages. A search engine indexes and searches available content.","Refine searches with specific keywords and assess source credibility, date and purpose.","An ISP provides internet connectivity. A URL identifies a resource using a scheme, host and optionally path; hyperlinks lead to another resource. Search engines index resources and retrieve relevant results using keywords.","Assess source author, evidence, date, bias and relevance; cross-check facts with reliable independent sources. Search engines provide rapid access to vast information but irrelevant, outdated or misleading results require filtering."],"A user opens a website in a browser after finding its address using a search engine.","Do not treat a browser and a search engine as the same software.",[["Web browser","Software that retrieves and displays web resources."],["Search engine","A service that helps find indexed information online."],["ISP","Organisation providing access to the internet."],["URL","Address identifying a resource on a network."]]),
lesson("Online services and protocols",["HTTPS supports encrypted website connections. FTP is associated with file transfer.","Blogs, forums, wikis and social platforms support different forms of publication and discussion.","Appropriate behaviour includes respectful messages, accurate information and protecting other people's privacy.","HTTP transfers web resources; HTTPS encrypts the connection using TLS (historically SSL). FTP transfers files but ordinary FTP does not encrypt them. Blogs publish posts, forums organise discussions, wikis support collaborative editing and social networks connect users.","Internet risks include scams, inappropriate or illegal material and privacy loss. Parents, schools and ISPs may restrict access using filters, parental controls and age-appropriate settings."],"A student checks that a login page uses HTTPS before entering credentials.","HTTPS is useful but does not guarantee that the website owner is trustworthy.",[["HTTP","Protocol used to transfer web resources."],["FTP","Protocol used to transfer files between computers."]])
]),
chapter(11,"File management","Organise files and reduce size without losing control of your work.",[
lesson("Folders and filenames",["Use a clear hierarchy of folders and descriptive filenames.","Keep versions identifiable, avoid unsafe characters and store related materials together.","Use import and export when moving data between compatible software packages.","Locate files using names, search or folders; open or import compatible files and save/export with meaningful names in a planned folder hierarchy. Print documents, screenshots, database reports, tables, charts and browser-rendered or HTML-source pages as required.","Application formats include DOC/DOCX for documents, XLS/XLSX for spreadsheets, SDB/ACCDB/ODB for databases, SDC for spreadsheets and PPT/PPTX for presentations. Generic formats improve exchange across software: CSV, TXT, RTF, PDF, CSS, HTM, JPG and PNG."],"Save a report as ICT_Unit6_Revision_v2 instead of Document1.","Before replacing a file, check that it is the intended version.",[["File hierarchy","Folders and subfolders arranged in levels."]]),
lesson("Compression and file types",["Lossless compression restores the original data exactly when decompressed.","Lossy compression removes selected data to reduce size, especially for images, audio and video.","Choose a format based on quality requirements, file size and compatibility.","CSV stores delimited tabular text; TXT stores unformatted text; RTF preserves basic formatting; PDF preserves page appearance; HTM stores web markup and CSS stores styles. GIF supports limited-colour images and animation; JPG suits photographs using lossy compression; PNG preserves sharp graphics with lossless compression.","ZIP and RAR archive and compress files losslessly, reducing storage use and transfer time. Already compressed files may shrink little; recipients need compatible extraction software."],"A logo with sharp text needs quality preservation. A large photo shared on a website may use controlled lossy compression.","Do not describe JPEG compression as lossless.",[["Lossless compression","Reducing file size while preserving all original data."],["Lossy compression","Reducing file size by discarding selected information."],["Generic file format","Format supported by multiple applications for exchanging data."]])
]),
chapter(12,"Images","Edit images accurately and choose sensible formats.",[
lesson("Image placement and editing",["Resize an image while preserving aspect ratio to avoid stretching.","Crop to remove unwanted edges and rotate or flip when required.","Position images precisely and use suitable text wrapping for the surrounding layout."],"A newsletter image is cropped to remove a distracting object without changing the width-to-height ratio of the remaining content.","Cropping removes part of the visible area. Resizing changes its dimensions.",[["Aspect ratio","The relationship between an image's width and height."]]),
lesson("Image quality and file size",["Pixel dimensions influence the detail of raster images.","Choose an appropriate file format and resolution for print, web or presentation use.","Compress images carefully and check that the result still meets the purpose."],"A large photograph compressed for a website loads faster but must remain clear enough to read.","Avoid upscaling a low-resolution image and expecting extra real detail.",[["Resolution","The amount of image detail, commonly indicated by pixel dimensions."]])
]),
chapter(13,"Layout","Build clear documents with tables, headings and repeating information.",[
lesson("Document structure",["Apply consistent margins, spacing, alignment and page settings.","Insert text and objects without breaking the visual reading order.","Use tables for structured information and set widths, padding and borders appropriately."],"A two-column information leaflet keeps related content aligned using a controlled layout.","Use tables when content is genuinely tabular, not to hide an inaccessible page structure.",[]),
lesson("Headers, footers and sections",["Headers and footers repeat items such as titles, dates or page numbers.","Page breaks and section settings control where content appears.","Check all pages after changing margins, columns or text size."],"A six-page report places the document title in the header and page numbering in the footer.","A page break starts a new page. A section break also allows different formatting.",[])
]),
chapter(14,"Styles","Create consistent reusable formatting throughout documents.",[
lesson("Text styles and hierarchy",["Styles apply predefined formatting to headings, body text and lists.","Serif and sans-serif fonts create different reading experiences. Readability matters more than decoration.","Paragraph spacing, indentation, emphasis and bullets should be consistent."],"Changing the Heading 2 style updates every section heading without editing each one.","Use styles instead of manually formatting every heading.",[["Style","A named set of reusable formatting instructions."]]),
lesson("Templates and corporate identity",["A document template stores a reusable structure and formatting.","Corporate identity applies consistent fonts, colours and logo treatment across material.","A consistent house style helps readers identify the organisation and navigate documents."],"A club creates a newsletter template with a fixed heading style and colour palette.","Do not overuse emphasis, colour or competing typefaces.",[["Template","A prepared reusable document layout."],["House style","Agreed visual rules for an organisation's publications."]])
]),
chapter(15,"Proofing","Find errors using software checks and human judgement.",[
lesson("Spelling, grammar and review",["Spellcheck catches many misspellings, but misses correctly spelled words used in the wrong context.","Grammar checks offer suggestions that require human review.","Proofread names, dates, figures, page layout and consistency before submitting work."],"The sentence 'Their is a result' might contain a real-word error that a simple spellcheck misses.","Spellcheck alone does not guarantee an accurate document.",[]),
lesson("Validation and verification",["Validation checks whether an input fits rules such as presence, data type, range, format and length.","Verification checks an entry against the source, for example double entry or visual comparison.","Both reduce errors in different ways, so neither replaces the other."],"An age field accepts 16 under a range check, but only verification finds that the original form said 15.","A valid value is not always the correct value.",[["Range check","Validation that a value lies within set limits."],["Double entry","Verification by comparing two independent entries of the same data."]])
]),
chapter(16,"Graphs and charts","Present data accurately using the right chart and labelling.",[
lesson("Selecting a chart",["Bar and column charts compare categories. Line graphs show change across a continuous scale such as time.","Pie charts show parts of a whole when the categories total the whole.","Select the source data carefully, especially for non-adjacent ranges."],"A line chart shows temperature each hour. A bar chart compares monthly device sales.","Chart type must match the relationship you need to communicate.",[["Data series","A related collection of values plotted on a chart."]]),
lesson("Formatting a chart",["Add a meaningful title, axis labels and units where relevant.","Use a legend when multiple series need distinguishing.","Check scale and decimal formatting so a chart does not mislead."],"A sales graph uses 'Revenue (QAR)' as its vertical axis label and months on the horizontal axis.","Some graphs use a secondary axis, but it must be labelled clearly.",[])
]),
chapter(17,"Document production","Control complex pages and move through long documents efficiently.",[
lesson("Page setup and formatting",["Select orientation, paper size, margins, columns and gutters to suit the output.","Use tabs, line spacing, paragraphs and page breaks to control text placement.","Apply bullets, numbering and appropriate emphasis consistently."],"A booklet uses a gutter margin so binding does not hide text.","Do not insert repeated spaces to simulate accurate alignment.",[["Gutter margin","Extra margin space reserved for binding."]]),
lesson("Editing and navigation",["Find and replace speeds consistent corrections across a document.","Bookmarks and hyperlinks help readers jump to related sections.","Use section and column breaks rather than pressing Enter repeatedly."],"An internal link takes a reader from a contents page to the correct heading.","Check links and navigation in the final exported format.",[])
]),
chapter(18,"Databases","Design tables, query records and present reliable reports.",[
lesson("Fields, records and tables",["A field stores a property such as StudentID or DateOfBirth. A record stores the fields for one item.","Choose suitable data types, lengths and validation rules before importing information.","A primary key uniquely identifies a record. Related tables link through matching key values."],"A Students table uses StudentID as its primary key and a Loans table stores StudentID as a foreign key.","Do not store numbers as text when calculations are required.",[["Primary key","A field, or combination of fields, that uniquely identifies a record."],["Foreign key","A field that refers to a key in another table."]]),
lesson("Queries and calculated fields",["Queries filter records using one or more criteria, then sort results if required.","Use comparison operators, AND, OR and wildcard patterns correctly.","Calculated fields derive results using expressions instead of storing duplicated values."],"To find Year 11 students with fees above 100, use Year = 11 AND Fees > 100.","AND requires both conditions. OR accepts either condition.",[["Query","An instruction to retrieve or manipulate selected data."]]),
lesson("Forms and reports",["Forms support structured data entry with clear labels and controlled input.","Reports present selected fields, grouping, sorting and summaries for a particular purpose.","Check headings, page breaks, field widths and totals before printing."],"A library report groups overdue loans by class and counts the number of records.","A query selects data. A report formats information for the reader.",[])
]),
chapter(19,"Presentations","Create purposeful presentations with consistent media and navigation.",[
lesson("Slides, objects and masters",["Use a clear hierarchy and enough contrast so slides remain readable.","Master slides keep shared elements consistent across the presentation.","Insert media, shapes, hyperlinks and action buttons only when they help the message."],"A school assembly deck uses one master for all title placements and logos.","Avoid excessive animation and crowded slide content.",[["Master slide","A reusable layout that controls repeated slide elements."]]),
lesson("Delivery and output",["Transitions move between slides while animations affect objects on a slide.","Slide shows may run with a presenter, be browsed individually or operate at a kiosk.","Export notes, handouts or an appropriate file format for the audience."],"A visitor information kiosk uses navigation buttons because there is no presenter advancing slides.","Test multimedia and links on the computer that will display the presentation.",[])
]),
chapter(20,"Spreadsheets","Create models using accurate formulae, functions and cell references.",[
lesson("References and calculations",["A relative reference changes when copied. An absolute reference such as $B$2 remains fixed.","Use cell references rather than typing repeated numbers directly into formulae.","Observe the usual order of operations and use brackets to make intentions clear."],"If B2 is a tax rate, =A5*$B$2 holds the tax reference fixed when the formula is filled down.","Mixed references such as $A2 fix only the column, while A$2 fixes only the row.",[["Relative reference","A cell reference that adjusts when copied."],["Absolute reference","A cell reference with fixed column and row markers."]]),
lesson("Functions and conditions",["SUM, AVERAGE, MIN, MAX and COUNT summarise ranges.","IF tests a condition and returns one of two results. COUNTIF and SUMIF use criteria.","VLOOKUP and HLOOKUP find data in reference tables. Match the lookup orientation to the data layout."],"=IF(C2>=50,\"Pass\",\"Retry\") returns a label from the mark in C2. =COUNTIF(A2:A20,\"Yes\") counts matching entries.","Quote text criteria and use correct absolute references when filling a lookup formula.",[["COUNTIF","Counts cells in a range that meet a criterion."],["VLOOKUP","Searches the first column of a table and returns a value from another column."]]),
lesson("Data management and output",["Sort on one or several fields, and filter with comparison rules.","Conditional formatting highlights records that satisfy a condition.","Set print area, page orientation, headers, footers and scaling before printing."],"A grade sheet highlights values below 50 and sorts pupils by class and score.","A visually correct spreadsheet can still have incorrect references. Verify the formulae.",[])
]),
chapter(21,"Website authoring","Use HTML and CSS to create organised, accessible web pages.",[
lesson("The web development layers",["HTML defines the content and structure of a page.","CSS controls appearance, spacing and layout. Scripts add interactive behaviour.","Keep semantic HTML and styling separate where practical."],"A navigation list is written in HTML, styled with CSS and opened by a button through JavaScript.","Content, presentation and behaviour are separate responsibilities.",[["HTML","Markup used to structure web page content."],["CSS","Rules that control the appearance of web content."]]),
lesson("HTML document and metadata",["The doctype tells the browser which HTML document type to expect.","The head contains information such as title, character encoding and viewport settings that is not shown as normal page content.","The body holds visible headings, paragraphs, images, lists, tables and links."],"A title element sets the browser-tab title. A viewport meta element helps the page size properly on phones.","The title is inside head, not the visible body heading.",[["Metadata","Information describing a document, often stored in its head."]]),
lesson("Links, tables and images",["Use descriptive hyperlinks with correct relative paths for local resources.","Tables use rows, header cells and data cells to represent tabular information.","Give images meaningful alternative text and choose suitable dimensions."],"A file link of 'images/logo.png' resolves relative to the current page location.","Always test hyperlinks after moving a website between folders.",[]),
lesson("CSS and shared styles",["A CSS rule combines a selector with one or more declarations.","External stylesheets keep formatting consistent across many pages.","Use classes for repeatable styling and IDs for individual elements when appropriate."],"The rule '.notice { color: blue; }' turns text blue for elements in the notice class.","The selector identifies the elements. The declarations determine their appearance.",[["CSS selector","The part of a CSS rule that identifies target elements."]])
])
];
export const allLessons=chapters.flatMap(ch=>ch.lessons.map((l,i)=>({...l,chapterId:ch.id,index:i,chapterTitle:ch.title})));
export const flashcards=allLessons.flatMap(l=>(l.terms||[]).map(([term,definition])=>({term,definition,chapterId:l.chapterId})));
